import type { InputInputProps, InputRootProps } from '@designharness/primitives';
import { Input as InputPrimitive } from '@designharness/primitives';
import { type ReactNode, forwardRef } from 'react';
import { cx, element } from './internal/classnames.js';

/**
 * Styled `Input` field.
 *
 * The primitive owns the whole accessibility story: label association (`htmlFor`),
 * `aria-required`, `aria-invalid`, the `aria-describedby` chain that joins the
 * description and the error text, and `role="alert"` on the error. This wrapper adds
 * classes and composition only — it never re-declares an `aria-*` attribute.
 */

/** Block class for every input selector in `styles/input.css`. */
export const INPUT_BLOCK = 'dh-input';

/** Modifier applied by the styled layer when the field carries an error message. */
export const INPUT_ERROR_MODIFIER = `${INPUT_BLOCK}--error`;

export type UIInputProps = InputRootProps & {
  /** Always-visible label text. Placeholder-only labels are a DESIGN.md prohibition. */
  label: ReactNode;
  /** Helper text rendered under the control and referenced by `aria-describedby`. */
  description?: ReactNode | undefined;
  /** Error message. Rendering it drives the invalid state and `role="alert"`. */
  error?: ReactNode | undefined;
  /** Placeholder copy — reserved for examples, never instructions. */
  placeholder?: string | undefined;
  /** Native input `type`. @default "text" */
  type?: 'text' | 'email' | 'number' | 'password' | 'search' | 'tel' | 'url' | 'date' | undefined;
  /** Escape hatch for the remaining native `<input>` attributes. */
  inputProps?: InputInputProps | undefined;
};

const isPresent = (value: ReactNode): boolean => value !== undefined && value !== null && value !== false && value !== '';

/** Field root. Adds the `dh-input` block class and nothing else. */
export const InputRoot = forwardRef<HTMLDivElement, InputRootProps>(function InputRoot(props, ref) {
  const { children, className, ...restProps } = props;
  return (
    <InputPrimitive.Root {...restProps} ref={ref} className={cx(INPUT_BLOCK, className)}>
      {children}
    </InputPrimitive.Root>
  );
});

/**
 * Convenience field: label + control + description + error, composed from the frozen
 * `input` anatomy parts. `required`, `disabled`, `readOnly`, `invalid`, `value` and
 * `onChange` keep the primitive's exact names and semantics.
 */
export function UIInput(props: UIInputProps): ReactNode {
  const { label, description, error, placeholder, type, inputProps, className, ...restProps } = props;
  const hasError = isPresent(error);

  return (
    <InputPrimitive.Root
      {...restProps}
      className={cx(INPUT_BLOCK, hasError ? INPUT_ERROR_MODIFIER : undefined, className)}
    >
      <InputPrimitive.Label>{label}</InputPrimitive.Label>
      <InputPrimitive.Input {...inputProps} placeholder={placeholder} type={type} />
      {isPresent(description) ? <InputPrimitive.Description>{description}</InputPrimitive.Description> : null}
      {hasError ? (
        <InputPrimitive.ErrorText icon={<span className={element(INPUT_BLOCK, 'error-glyph')}>!</span>}>
          {error}
        </InputPrimitive.ErrorText>
      ) : null}
    </InputPrimitive.Root>
  );
}

/** Callable field component plus the frozen compound parts for custom composition. */
export interface InputComponent {
  (props: UIInputProps): ReactNode;
  Root: typeof InputRoot;
  Label: typeof InputPrimitive.Label;
  Input: typeof InputPrimitive.Input;
  Description: typeof InputPrimitive.Description;
  ErrorText: typeof InputPrimitive.ErrorText;
}

export const Input: InputComponent = Object.assign(UIInput, {
  Root: InputRoot,
  Label: InputPrimitive.Label,
  Input: InputPrimitive.Input,
  Description: InputPrimitive.Description,
  ErrorText: InputPrimitive.ErrorText,
});

/*
 * Input — styling for the frozen `input` anatomy: `root`, `label`, `input`,
 * `description`, `error-text`. DESIGN.md "Components": the label is always visible, the
 * placeholder carries examples only, and the error message is an icon *plus* wording —
 * colour is never the error signal.
 */

@layer components {
  [data-part="root"]:where([data-scope="input"]) {
    display: flex;
    flex-direction: column;
    gap: var(--space-xxs);
    box-sizing: border-box;
    inline-size: 100%;
    font-family: var(--font-family-body);
    font-size: var(--font-size-body-md);
    color: var(--color-text-primary);
  }

  /* `label-caps` is the only uppercase style and is reserved for exactly this and headers. */
  [data-part="label"]:where([data-scope="input"]) {
    font-family: var(--font-family-body);
    font-size: var(--font-size-label-caps);
    font-weight: var(--font-weight-label-caps);
    line-height: var(--line-height-label-caps);
    letter-spacing: var(--letter-spacing-label-caps);
    text-transform: uppercase;
    color: var(--color-text-secondary);
    transition: color var(--duration-fast) var(--easing-standard);
  }

  /* Required fields are marked with a real glyph, so the requirement is not a colour. */
  [data-part="label"][data-required]:where([data-scope="input"])::after {
    content: "*";
    margin-inline-start: var(--space-xxs);
    color: var(--color-danger);
  }

  [data-part="input"]:where([data-scope="input"]) {
    box-sizing: border-box;
    inline-size: 100%;
    min-block-size: var(--input-height);
    padding-block: var(--space-xxs);
    padding-inline: var(--input-padding-inline);
    border-width: var(--border-width-hairline);
    border-style: solid;
    /* `--color-border-strong` clears WCAG 2.2 SC 1.4.11 against every surface. */
    border-color: var(--color-border-strong);
    border-radius: var(--radius-sm);
    background-color: var(--color-surface);
    color: var(--color-text-primary);
    font-family: inherit;
    font-size: var(--font-size-body-md);
    line-height: var(--line-height-body-md);
    appearance: textfield;
    transition:
      border-color var(--duration-fast) var(--easing-standard),
      background-color var(--duration-fast) var(--easing-standard);
  }

  [data-part="input"]:where([data-scope="input"])::placeholder {
    color: var(--color-text-secondary);
    opacity: 1;
  }

  [data-part="input"]:where([data-scope="input"]):hover {
    border-color: var(--color-border-strong);
    background-color: var(--color-surface-sunken);
  }

  /* --- states, each with a non-colour cue -------------------------------------- */

  [data-part="input"][data-invalid]:where([data-scope="input"]) {
    border-width: var(--border-width-strong);
    border-color: var(--color-danger);
  }

  [data-part="input"][data-disabled]:where([data-scope="input"]) {
    background-color: var(--color-surface-sunken);
    border-color: var(--color-border-subtle);
    color: var(--color-text-secondary);
    cursor: default;
    opacity: 0.55;
  }

  [data-part="input"][data-readonly]:where([data-scope="input"]) {
    background-color: var(--color-surface-sunken);
    border-style: dashed;
    color: var(--color-text-primary);
  }

  [data-part="label"][data-focus]:where([data-scope="input"]) {
    color: var(--color-text-primary);
  }

  /* A field in error names itself in the label too, before the message is reached. */
  .dh-input--error [data-part="label"] {
    color: var(--color-danger);
    text-decoration: underline;
    text-underline-offset: var(--space-xxs);
  }

  /* --- help + error text -------------------------------------------------------- */

  [data-part="description"]:where([data-scope="input"]) {
    /* Fluid helper copy: a field in a 300px rail and one in an 800px stage both stay
       readable with no breakpoint jump (DESIGN.md "Typography"). */
    font-size: clamp(
      var(--font-size-body-sm),
      calc(var(--font-size-body-sm) + 0.25cqi),
      var(--font-size-body-md)
    );
    line-height: var(--line-height-body-sm);
    color: var(--color-text-secondary);
  }

  [data-part="error-text"]:where([data-scope="input"]) {
    display: flex;
    align-items: center;
    gap: var(--space-xxs);
    font-size: var(--font-size-body-sm);
    line-height: var(--line-height-body-sm);
    font-weight: var(--font-weight-body-md);
    color: var(--color-danger);
  }

  .dh-input__error-glyph {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    box-sizing: border-box;
    inline-size: var(--space-md);
    block-size: var(--space-md);
    border-radius: var(--radius-full);
    background-color: var(--color-danger);
    color: var(--color-on-danger);
    font-family: var(--font-family-body);
    font-size: var(--font-size-label-caps);
    font-weight: var(--font-weight-label-caps);
    line-height: var(--line-height-label-caps);
  }
}

/**
 * Class-name helpers for the styled layer.
 *
 * The styled layer's only DOM contribution is *class names*: every structural and
 * state signal (`data-scope`, `data-part`, `data-open`, `data-disabled`, `aria-*`)
 * is owned by `@designharness/primitives` and is never re-implemented, renamed or
 * overridden here (TOKEN-API.md §5). Component CSS is authored against those
 * attributes plus the `dh-<component>` block / `dh-<component>--<variant>` modifier
 * classes produced by these helpers.
 */

/** Any value that a class list may legitimately contain. */
export type ClassValue = string | false | null | undefined;

/** Join a class list, dropping empty entries and collapsing to a single string. */
export function cx(...values: readonly ClassValue[]): string {
  const parts: string[] = [];
  for (const value of values) {
    if (typeof value === 'string' && value.length > 0) parts.push(value);
  }
  return parts.join(' ');
}

/**
 * BEM-ish modifier builder: `modifier('dh-button', 'primary')` → `dh-button--primary`.
 * A `false`/`undefined` modifier yields `undefined` so it can be passed to `cx` directly.
 */
export function modifier(block: string, value: string | false | null | undefined): string | undefined {
  if (!value) return undefined;
  return `${block}--${value}`;
}

/**
 * Element builder: `element('dh-button', 'spinner')` → `dh-button__spinner`.
 * Elements are markup *the styled layer itself renders* — never anatomy parts.
 */
export function element(block: string, name: string): string {
  return `${block}__${name}`;
}

/**
 * Merge a consumer `className` after the styled-layer classes so a host app can add
 * utility classes without ever losing the tokenized base (source order, no `!important`).
 */
export function withConsumerClass(styled: string, className: ClassValue): string {
  return cx(styled, className);
}
